import assert from 'node:assert/strict';
import test from 'node:test';
import { listFeaturedProducts } from '../lib/catalog.js';
import { renderProductCards } from '../app/products/page.js';

test('catalog filters, sorts, and preserves input', () => {
  const products = [
    { id: 'desk', name: 'Desk', price: 499, stock: 2, featured: true },
    { id: 'lamp', name: 'Lamp', price: 49.5, stock: 4, featured: true },
    { id: 'chair', name: 'Chair', price: 199, stock: 0, featured: true },
    { id: 'mat', name: 'Mat', price: 20, stock: 8, featured: false }
  ];
  const before = structuredClone(products);
  assert.deepEqual(listFeaturedProducts(products).map(({ id }) => id), ['lamp', 'desk']);
  assert.deepEqual(products, before);
});

test('server rendering emits accessible commerce evidence', () => {
  const html = renderProductCards([{ id: 'lamp', name: 'Lamp', price: 49.5, stock: 4, featured: true }]);
  assert.match(html, /data-product-id=["']lamp["']/);
  assert.match(html, /Lamp/);
  assert.match(html, /\$49\.50/);
  assert.match(html, /article|listitem/);
});
